downloadFramed.handler:
function downloadFramed(args, ctx) {
  try {
    if (typeof window === "undefined" || typeof document === "undefined") {
      ctx.triggerActionEvent("error", { error: "Not available in this environment." })
      return
    }
    var source = document.getElementById(args.elementId || "qr-frame-capture")
    if (!source) {
      ctx.triggerActionEvent("error", { error: "Framed preview element not found." })
      return
    }

    // Inline all computed styles onto a deep clone so the serialized markup renders
    // identically without external stylesheets. Also inline any nested <img> sources.
    function inlineStyles(srcEl, dstEl) {
      var cs = window.getComputedStyle(srcEl)
      var decl = ""
      for (var i = 0; i < cs.length; i++) {
        var prop = cs[i]
        decl += prop + ":" + cs.getPropertyValue(prop) + ";"
      }
      dstEl.setAttribute("style", decl)
      var sChildren = srcEl.children
      var dChildren = dstEl.children
      for (var j = 0; j < sChildren.length; j++) {
        if (dChildren[j]) { inlineStyles(sChildren[j], dChildren[j]) }
      }
    }

    var rect = source.getBoundingClientRect()
    var width = Math.max(1, Math.ceil(rect.width))
    var height = Math.max(1, Math.ceil(rect.height))

    var clone = source.cloneNode(true)
    inlineStyles(source, clone)
    // Neutralize layout-affecting margins on the root clone.
    clone.style.margin = "0"
    clone.style.transform = "none"

    var serializer = new XMLSerializer()
    var cloneMarkup = serializer.serializeToString(clone)

    var svgString =
      '<svg xmlns="http://www.w3.org/2000/svg" width="' + width + '" height="' + height + '">' +
      '<foreignObject x="0" y="0" width="' + width + '" height="' + height + '">' +
      '<div xmlns="http://www.w3.org/1999/xhtml">' + cloneMarkup + '</div>' +
      '</foreignObject></svg>'

    function triggerFileDownload(href, filename) {
      var a = document.createElement("a")
      a.href = href
      a.download = filename
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
    }

    if (args.format === "svg") {
      var blob = new Blob([svgString], { type: "image/svg+xml;charset=utf-8" })
      var url = URL.createObjectURL(blob)
      triggerFileDownload(url, "qr-framed.svg")
      setTimeout(function () { URL.revokeObjectURL(url) }, 1000)
      ctx.triggerActionEvent("done", {})
      return
    }

    var scale = (args.px && width) ? (args.px / width) : 2
    if (!isFinite(scale) || scale <= 0) { scale = 2 }

    var canvas = document.createElement("canvas")
    canvas.width = Math.ceil(width * scale)
    canvas.height = Math.ceil(height * scale)
    var ctx2d = canvas.getContext("2d")

    var img = new Image()
    img.onload = function () {
      try {
        ctx2d.setTransform(scale, 0, 0, scale, 0, 0)
        ctx2d.drawImage(img, 0, 0)
        canvas.toBlob(function (pngBlob) {
          if (!pngBlob) {
            ctx.triggerActionEvent("error", { error: "Failed to rasterize framed QR." })
            return
          }
          var pngUrl = URL.createObjectURL(pngBlob)
          triggerFileDownload(pngUrl, "qr-framed.png")
          setTimeout(function () { URL.revokeObjectURL(pngUrl) }, 1000)
          ctx.triggerActionEvent("done", {})
        }, "image/png")
      } catch (e2) {
        ctx.triggerActionEvent("error", { error: (e2 && e2.message) ? e2.message : String(e2) })
      }
    }
    img.onerror = function () {
      ctx.triggerActionEvent("error", { error: "Could not render framed QR image. The frame may contain content that cannot be exported." })
    }
    img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svgString)
  } catch (e) {
    ctx.triggerActionEvent("error", { error: (e && e.message) ? e.message : String(e) })
  }
}

downloadBlob.handler:
function downloadBlob(args, ctx) {
  if (typeof document === 'undefined') {
    return
  }
  const content = args.content == null ? '' : String(args.content)
  const filename = args.filename == null ? 'download' : String(args.filename)
  const mimeType = args.mimeType == null ? 'text/csv;charset=utf-8' : String(args.mimeType)

  const blob = new Blob([content], { type: mimeType })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename
  anchor.style.display = 'none'
  document.body.appendChild(anchor)
  anchor.click()
  document.body.removeChild(anchor)

  // Revoke on the next tick so the download has begun.
  setTimeout(() => {
    URL.revokeObjectURL(url)
    ctx.triggerActionEvent('done', { filename })
  }, 0)
}

